import numpy as np
from PIL import Image, ImageDraw, ImageFont
im=np.array(Image.open('chess_board.png').convert('RGB')).astype(int)
L=np.array([240,217,181]); D=np.array([181,136,99]); sq=80
def base(r,c): return L if (r+c)%2==0 else D
B={'king':'♚','queen':'♛','rook':'♜','bishop':'♝','knight':'♞','pawn':'♟'}
W={'king':'♔','queen':'♕','rook':'♖','bishop':'♗','knight':'♘','pawn':'♙'}
FP='/fonts/noto.ttf'
def render(ch,size):
    f=ImageFont.truetype(FP,size)
    can=Image.new('L',(300,300),0); ImageDraw.Draw(can).text((80,80),ch,font=f,fill=255)
    a=np.array(can)>128; ys,xs=np.where(a)
    return a[ys.min():ys.max()+1, xs.min():xs.max()+1]
tpl={}
for col,d in [('B',B),('W',W)]:
    for name,ch in d.items(): tpl[(col,name)]=[render(ch,s) for s in (54,55,56,57,58)]
def ink_of(r,c):
    crop=im[r*sq:(r+1)*sq, c*sq:(c+1)*sq]
    return np.abs(crop-base(r,c)).sum(axis=2)>60
def scores(ink,col):
    out={}
    for name in (B if col=='B' else W):
        best=0
        for r in tpl[(col,name)]:
            H,Wd=ink.shape
            if r.shape[0]>H or r.shape[1]>Wd: continue
            for y0 in range(0,H-r.shape[0]+1,2):
                for x0 in range(0,Wd-r.shape[1]+1,2):
                    sub=ink[y0:y0+r.shape[0],x0:x0+r.shape[1]]
                    inter=(sub&r).sum(); uni=(sub|r).sum()
                    if uni and inter/uni>best: best=inter/uni
        out[name]=round(best,3)
    return out
for (r,c,col) in [(3,6,'B'),(3,5,'B'),(2,2,'B'),(3,3,'B'),(2,0,'B'),(0,3,'B'),(5,2,'W'),(6,4,'W'),(7,4,'W'),(7,2,'W'),(7,0,'W'),(3,4,'W')]:
    print((r,c),col,scores(ink_of(r,c),col))
PY
